// Phase 2 -- Breaking News Gate
// Find high-score recent articles not yet covered in blog
// ES5/ASCII only -- no template literals, no Unicode

var newsItem = $('Fetch News Feed').item.json;
var blogItem = $('Fetch Blog Feed').item.json;

var now = new Date();
var SCORE_THRESHOLD = 8;       // relevance_score >= 8 triggers post
var LOOKBACK_HOURS = 4;        // articles must be < 4h old
var BLOG_COOLDOWN_HOURS = 3;   // no breaking post if one exists in last 3h
var cutoff = new Date(now.getTime() - LOOKBACK_HOURS * 3600000);
var blogCutoff = new Date(now.getTime() - BLOG_COOLDOWN_HOURS * 3600000);

// Guard: news feed error
var articles = (newsItem && newsItem.articles) ? newsItem.articles : [];
if (!articles.length) {
  return [{ json: { shouldPost: false, reason: 'news_feed_empty_or_error' } }];
}

// Recent high-score articles
var candidates = [];
for (var i = 0; i < articles.length; i++) {
  var a = articles[i];
  var score = a.relevance_score || 0;
  if (score < SCORE_THRESHOLD) continue;
  var pub = a.published_at || '';
  var pubDate = new Date(pub.replace('Z', '+00:00'));
  if (isNaN(pubDate.getTime())) continue;
  if (pubDate < cutoff) continue;
  candidates.push(a);
}

if (!candidates.length) {
  return [{ json: { shouldPost: false, reason: 'no_high_score_recent_articles', checked: articles.length } }];
}

// Sort candidates by score desc
candidates.sort(function(x, y) { return (y.relevance_score || 0) - (x.relevance_score || 0); });

// Check blog cooldown -- skip if a breaking post already exists in last 3h
var recentPosts = (blogItem && blogItem.posts) ? blogItem.posts : [];
for (var j = 0; j < recentPosts.length; j++) {
  var p = recentPosts[j];
  var tags = p.tags || [];
  var pubP = new Date((p.published_at || '').replace('Z', '+00:00'));
  if (isNaN(pubP.getTime())) continue;
  if (pubP >= blogCutoff && tags.indexOf('breaking') !== -1) {
    return [{ json: { shouldPost: false, reason: 'cooldown_active', last_breaking: p.published_at } }];
  }
}

// Dedup: skip if article headline keywords already appear in recent blog title
// Use simple word overlap check on post titles from last 24h
var dayAgo = new Date(now.getTime() - 24 * 3600000);
var recentTitles = [];
for (var k = 0; k < recentPosts.length; k++) {
  var rp = recentPosts[k];
  var rpPub = new Date((rp.published_at || '').replace('Z', '+00:00'));
  if (!isNaN(rpPub.getTime()) && rpPub >= dayAgo) {
    recentTitles.push((rp.title || '').toLowerCase());
  }
}

function wordsOf(str) {
  return str.toLowerCase().split(/[\s\W]+/).filter(function(w) { return w.length > 4; });
}

var chosen = null;
for (var c = 0; c < candidates.length; c++) {
  var cand = candidates[c];
  var candWords = wordsOf(cand.title || '');
  var covered = false;
  for (var t = 0; t < recentTitles.length; t++) {
    var matchCount = 0;
    for (var w = 0; w < candWords.length; w++) {
      if (recentTitles[t].indexOf(candWords[w]) !== -1) matchCount++;
    }
    // If 2+ meaningful words match a recent post title, consider it covered
    if (matchCount >= 2) { covered = true; break; }
  }
  if (!covered) { chosen = cand; break; }
}

if (!chosen) {
  return [{ json: { shouldPost: false, reason: 'all_candidates_already_covered', candidates: candidates.length } }];
}

// Build Claude prompt for breaking news post (350-500 words)
var headline = chosen.title || 'Breaking Crypto News';
var source = chosen.source || '';
var summary = chosen.summary || chosen.title || '';
var sentiment = chosen.sentiment || 'neutral';
var score = chosen.relevance_score || 0;
var url = chosen.url || '';

var sys = 'You are AlphaForgeAI, a battle-tested crypto market analyst. You write sharp, focused breaking news commentary for the AlphaForgeAI blog. Your audience is active crypto traders. Write with authority. Take a directional stance (Bullish, Bearish, or Neutral) on what this news means for the market. Be direct. Cover WHY this matters, WHAT traders should watch, and WHAT the market reaction means. Do NOT invent prices or data not provided. No financial advice. No buy/sell recommendations. No price targets. Length: 350-500 words. Format in markdown with ## section headers. Sections: ## Breaking: [short punchy subheadline], ## Why This Matters, ## Market Reaction Watch, ## AlphaForgeAI Take. End every post with: This post is for informational purposes only and does not constitute financial advice.';

var userPrompt = 'Write a breaking news blog post about this story. Headline: ' + headline + '. Source: ' + source + '. Summary: ' + summary + '. Current sentiment signal: ' + sentiment + '. Relevance score: ' + score + '/10. Do not repeat the headline verbatim as the post title -- write a sharp editorial title. Focus on the market implications.';

var claudeBody = JSON.stringify({
  model: 'claude-sonnet-4-5',
  max_tokens: 1200,
  system: sys,
  messages: [{ role: 'user', content: userPrompt }]
});

return [{
  json: {
    shouldPost: true,
    article: chosen,
    claude_body: claudeBody
  }
}];

// Parse Claude response and build blog ingest payload
var claudeResp = $input.item.json;
var gateData = $('Evaluate + Gate').item.json;
var article = gateData.article || {};

var content = '';
if (claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text) {
  content = claudeResp.content[0].text;
}

if (!content) {
  return [{ json: { error: 'claude_empty_response', raw: JSON.stringify(claudeResp) } }];
}

// Extract editorial title from first markdown line
var lines = content.split('\n').filter(function(l) { return l.trim(); });
var firstLine = lines[0] || '';
var title = firstLine.startsWith('#')
  ? firstLine.replace(/^#+\s*/, '').trim()
  : 'Breaking: ' + (article.title || 'Crypto Alert');

// Generate slug
var now = new Date();
var dateStr = now.toISOString().split('T')[0];
var timeStr = now.toISOString().split('T')[1].substring(0, 5).replace(':', '');
var slug = 'breaking-' + dateStr + '-' + timeStr;

// Summary from first non-header line
var summary = '';
for (var i = 0; i < lines.length; i++) {
  if (!lines[i].startsWith('#') && lines[i].length > 40) {
    summary = lines[i].replace(/[*_`]/g, '').substring(0, 200);
    break;
  }
}
if (!summary) summary = 'Breaking crypto market news from AlphaForgeAI.';

// Extract asset symbols mentioned
var assetRegex = /\b(BTC|ETH|SOL|XRP|BNB|AVAX|DOGE|ADA|DOT|MATIC|LINK|UNI|AAVE|SNX|CRV|COMP|INJ|OP|ARB|SUI|APT|NEAR|FIL|LTC|BCH|SHIB|PEPE|FLOKI|BONK|WIF|POL)\b/g;
var assetMatches = content.match(assetRegex) || [];
var assets = [];
var seenAssets = {};
for (var k = 0; k < assetMatches.length; k++) {
  if (!seenAssets[assetMatches[k]]) {
    assets.push(assetMatches[k]);
    seenAssets[assetMatches[k]] = true;
  }
}
if (!assets.length) assets = ['BTC'];

var sources = article.url ? [article.url] : [];

return [{
  json: {
    schema_version: 1,
    posts: [{
      slug: slug,
      title: title,
      published_at: now.toISOString(),
      summary: summary,
      content: content,
      sources: sources,
      assets: assets,
      tags: ['breaking', 'market'],
      author: 'AlphaForgeAI'
    }]
  }
}];

// Log skip reason to n8n execution log
var d = $input.item.json;
return [{ json: { skipped: true, reason: d.reason || 'unknown', detail: d } }];
